import os
from pathlib import Path
import csv

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190127", "20190128"]
lines = ["冀宁线", "川气东送"]

results = {}
for line in lines:
    total_segments = 0
    zero_days = 0
    segment_zero_days = {}
    for date in dates:
        csv_path = DIR / f"{date}_pipeline.csv"
        with open(csv_path, "r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            for row in reader:
                if row["管道划分"] == line:
                    seg_key = f'{row["起点站名"]}→{row["终点站名"]}'
                    total_segments += 1
                    flow = float(row["管道流量"])
                    if flow == 0:
                        zero_days += 1
                        segment_zero_days[seg_key] = segment_zero_days.get(seg_key, 0) + 1
    results[line] = {
        "total_segments": total_segments,
        "zero_days": zero_days,
        "zero_ratio": zero_days / total_segments if total_segments > 0 else 0,
        "segment_zero_days": segment_zero_days
    }

for line in lines:
    r = results[line]
    print(f"{line}: total_segments={r['total_segments']}, zero_days={r['zero_days']}, zero_ratio={r['zero_ratio']:.4f}")
    for seg, count in sorted(r["segment_zero_days"].items(), key=lambda x: -x[1]):
        print(f"  {seg}: {count} zero_day(s)")

