import os
import csv
from pathlib import Path

NODE_DIR = Path(os.environ["NODE_FLOW_DIR"])

files = ["20191106_node.csv", "20191107_node.csv", "20191118_node.csv"]
stations = ["靖边站", "南通站"]

# per-file absolute flow per station
per_file = {f: {s: 0.0 for s in stations} for f in files}

for fname in files:
    path = NODE_DIR / fname
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        # find the flow column
        flow_col = None
        for col in reader.fieldnames:
            if "流量" in col and "计算" in col:
                flow_col = col
                break
        if flow_col is None:
            # fallback: any column with 流量
            for col in reader.fieldnames:
                if "流量" in col:
                    flow_col = col
                    break
        for row in reader:
            station = row.get("站点名称", "")
            if station in stations:
                val = row.get(flow_col, "")
                try:
                    per_file[fname][station] += abs(float(val))
                except (ValueError, TypeError):
                    pass

print("=== Per-file absolute flows (across all pipelines) ===")
for fname in files:
    for s in stations:
        print(f"  {s} - {fname}: {per_file[fname][s]:.3f}")

print()
print("=== Cumulative absolute node flows (window 2019-11-06 to 2019-11-18) ===")
totals = {s: 0.0 for s in stations}
for s in stations:
    for fname in files:
        totals[s] += per_file[fname][s]
    print(f"  {s}: {totals[s]:.3f}")

print()
print("=== Comparison ===")
higher = max(stations, key=lambda s: totals[s])
lower = min(stations, key=lambda s: totals[s])
print(f"  Higher: {higher} ({totals[higher]:.3f})")
print(f"  Lower:  {lower} ({totals[lower]:.3f})")
print(f"  Difference: {totals[higher] - totals[lower]:.3f}")

# Now remove the highest-peak day (the day with the largest total absolute flow across both stations)
print()
print("=== Remove highest-peak day ===")
day_totals = {}
for fname in files:
    day_total = sum(per_file[fname][s] for s in stations)
    day_totals[fname] = day_total
    print(f"  {fname}: total={day_total:.3f}")

peak_day = max(day_totals, key=lambda f: day_totals[f])
print(f"  Peak day: {peak_day} (total={day_totals[peak_day]:.3f})")

reduced_totals = {s: 0.0 for s in stations}
for s in stations:
    for fname in files:
        if fname != peak_day:
            reduced_totals[s] += per_file[fname][s]

print()
print("=== After removing peak day ===")
for s in stations:
    print(f"  {s}: {reduced_totals[s]:.3f}")

higher2 = max(stations, key=lambda s: reduced_totals[s])
